{
  "items": [
    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "Behrend.bound_aux",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {n d : ℕ}, d ≠ 0 → 2 ≤ n → ↑d ^ (n - 2) / ↑n ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Behrend.bound_aux'",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ (n d : ℕ), ↑(d ^ n) / ↑(n * d ^ 2) ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Behrend.roth_lower_bound_explicit",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, 4096 ≤ N → ↑N * Real.exp (-4 * √(Real.log ↑N)) < ↑(rothNumberNat N)"
    },
    {
      "name": "LindemannWeierstrass.exp_polynomial_approx",
      "module_name": "Mathlib.NumberTheory.Transcendental.Lindemann.AnalyticalPart",
      "kind": "theorem",
      "type": "∀ (f : Polynomial ℤ),\n  Polynomial.eval 0 f ≠ 0 →\n    ∃ c,\n      ∀ p > (Polynomial.eval 0 f).natAbs,\n        Nat.Prime p →\n          ∃ n,\n            ¬↑p ∣ n ∧\n              ∃ gp,\n                gp.natDegree ≤ p * f.natDegree - 1 ∧\n                  ∀ {r : ℂ},\n                    r ∈ f.aroots ℂ → ‖n • Complex.exp r - p • (Polynomial.aeval r) gp‖ ≤ c ^ p / ↑(p - 1).factorial"
    },
    {
      "name": "Liouville.exists_pos_real_of_irrational_root",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {α : ℝ},\n  Irrational α →\n    ∀ {f : Polynomial ℤ},\n      f ≠ 0 →\n        Polynomial.eval α (Polynomial.map (algebraMap ℤ ℝ) f) = 0 →\n          ∃ A, 0 < A ∧ ∀ (a : ℤ) (b : ℕ), 1 ≤ (↑b + 1) ^ f.natDegree * (|α - ↑a / (↑b + 1)| * A)"
    },
    {
      "name": "Polynomial.Separable.aeval_derivative_ne_zero",
      "module_name": "Mathlib.FieldTheory.Separable",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {S : Type v} [inst_1 : CommSemiring S] [Nontrivial S] [inst_3 : Algebra R S]\n  {p : Polynomial R},\n  p.Separable → ∀ {x : S}, (Polynomial.aeval x) p = 0 → (Polynomial.aeval x) (Polynomial.derivative p) ≠ 0"
    }
  ]
}
